"use client";
import { type CSSProperties, useId, useLayoutEffect, useRef, useState } from "react";
import { MenuInternalStyles, MenuRollingLabel, useMenuDismiss, useMenuState } from "./menu-shared";
export interface MorphingPillLink {
  id: string;
  label: string;
  href: string;
  badge?: string;
}
export interface MorphingPillMenuProps {
  links: readonly MorphingPillLink[];
  image?: string;
  imageAlt?: string;
  imageHref?: string;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  onNavigate?: (link: MorphingPillLink) => void;
  duration?: number;
  stagger?: number;
  background?: string;
  color?: string;
  maxWidth?: number;
  className?: string;
  style?: CSSProperties;
}
export function MorphingPillMenu({
  links,
  image,
  imageAlt = "",
  imageHref,
  open,
  defaultOpen = false,
  onOpenChange,
  onNavigate,
  duration = 0.65,
  stagger = 0.018,
  background = "#292929",
  color = "#f4f2ec",
  maxWidth = 600,
  className,
  style,
}: MorphingPillMenuProps) {
  const [expanded, setExpanded] = useMenuState(open, defaultOpen, onOpenChange);
  const root = useRef<HTMLElement>(null),
    content = useRef<HTMLDivElement>(null),
    trigger = useRef<HTMLButtonElement>(null);
  const [height, setHeight] = useState(252);
  const id = useId();
  useMenuDismiss(expanded, setExpanded, root, trigger);
  useLayoutEffect(() => {
    const node = content.current;
    if (!node) return;
    const measure = () => setHeight(node.scrollHeight);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(node);
    return () => observer.disconnect();
  }, []);
  return (
    <div
      className={className}
      style={{ width: "100%", display: "flex", justifyContent: "center", ...style }}
    >
      <MenuInternalStyles />
      <nav
        ref={root}
        aria-label="Main navigation"
        data-pill-open={expanded}
        className="z-am-animated"
        style={
          {
            position: "relative",
            background,
            color,
            width: expanded ? `min(${maxWidth}px,100%)` : 120,
            height: expanded ? Math.min(height + 48, 10000) : 48,
            maxHeight: "calc(100dvh - 40px)",
            borderRadius: expanded ? 26 : 999,
            overflow: "hidden",
            transition: `width ${duration}s cubic-bezier(.2,.8,.2,1),height ${duration}s cubic-bezier(.2,.8,.2,1),border-radius ${duration}s`,
            "--z-am-duration": `${duration}s`,
          } as CSSProperties
        }
      >
        <div
          style={{ height: 48, display: "flex", justifyContent: "center", alignItems: "center" }}
        >
          <button
            ref={trigger}
            type="button"
            className="z-am-reset"
            aria-expanded={expanded}
            aria-controls={id}
            aria-label={expanded ? "Close navigation menu" : "Open navigation menu"}
            onClick={() => setExpanded(!expanded)}
            style={{
              minHeight: 44,
              padding: "0 18px",
              display: "flex",
              alignItems: "center",
              gap: 12,
              fontSize: 15,
            }}
          >
            {expanded ? "Close" : "Menu"}
            <span
              aria-hidden
              style={{
                width: 26,
                height: 26,
                borderRadius: 999,
                background: "#fff2",
                display: "grid",
                placeItems: "center",
                fontSize: 20,
                transform: expanded ? "rotate(45deg)" : "rotate(0deg)",
                transition: `transform ${duration}s`,
              }}
            >
              +
            </span>
          </button>
        </div>
        <div
          id={id}
          inert={!expanded}
          aria-hidden={!expanded}
          style={{
            overflow: "auto",
            height: "calc(100% - 48px)",
            opacity: expanded ? 1 : 0,
            transition: `opacity ${duration * 0.5}s`,
          }}
        >
          <div
            ref={content}
            className="z-am-pill-grid"
            style={!image ? { gridTemplateColumns: "1fr" } : undefined}
          >
            {image &&
              (imageHref ? (
                <a
                  href={imageHref}
                  aria-label={imageAlt || "View collection"}
                  onClick={() => setExpanded(false)}
                >
                  <img className="z-am-pill-image" src={image} alt={imageAlt} />
                </a>
              ) : (
                <img className="z-am-pill-image" src={image} alt={imageAlt} />
              ))}
            <div
              style={{
                display: "flex",
                flexDirection: "column",
                justifyContent: "center",
                alignItems: "flex-start",
                minWidth: 0,
              }}
            >
              {links.map((link, index) => (
                <a
                  key={link.id}
                  className="z-am-reset"
                  href={link.href}
                  aria-label={link.label}
                  onClick={() => {
                    setExpanded(false);
                    onNavigate?.(link);
                  }}
                  style={{
                    fontSize: "clamp(20px,3vw,34px)",
                    letterSpacing: "-.045em",
                    lineHeight: 1.3,
                    minHeight: 44,
                    display: "flex",
                    alignItems: "center",
                    maxWidth: "100%",
                    gap: 10,
                  }}
                >
                  <span style={{ overflow: "hidden" }}>
                    <MenuRollingLabel
                      text={link.label}
                      stagger={stagger}
                      delay={index * stagger * 4}
                    />
                  </span>
                  {link.badge && (
                    <small style={{ color: "#ff653b", fontSize: 12, letterSpacing: 0 }}>
                      {link.badge}
                    </small>
                  )}
                </a>
              ))}
            </div>
          </div>
        </div>
      </nav>
    </div>
  );
}
